create table public.exam_sessions (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,exam_id uuid not null references public.exams(id) on delete restrict,classroom_id uuid not null references public.classrooms(id) on delete restrict,student_id uuid references public.students(id) on delete restrict,starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'SCHEDULED' check(status in('SCHEDULED','OPEN','CLOSED')),calendar_event_id uuid references public.calendar_events(id) on delete set null,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),check(ends_at>starts_at));create index exam_sessions_tenant_schedule_idx on public.exam_sessions(tenant_id,starts_at);alter table public.exam_sessions enable row level security;revoke all on public.exam_sessions from anon,authenticated;create policy exam_sessions_select_tenant on public.exam_sessions for select to authenticated using(tenant_id=public.current_tenant_id());insert into public.permissions(code,name,description) values('exam_sessions.read','Read exam sessions','View exam schedule'),('exam_sessions.create','Create exam sessions','Schedule exams'),('exam_sessions.update','Update exam sessions','Maintain exam schedule'),('exam_sessions.delete','Delete exam sessions','Delete exam sessions') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'exam_sessions.%' on conflict do nothing;
